import pandas as pd, requests, io, re
HEAD = {'User-Agent':'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 Chrome/120 Safari/537.36'}
for name, url, needle in [('RED','https://en.wikipedia.org/wiki/The_Red_Tour','Nonthaburi'),
                          ('ERAS','https://en.wikipedia.org/wiki/The_Eras_Tour','Vienna')]:
    html = requests.get(url, headers=HEAD, timeout=60).text
    tables = pd.read_html(io.StringIO(html))
    print(f'==== {name}: {len(tables)} tables')
    for i,t in enumerate(tables):
        cols=[str(c) for c in t.columns]
        s = t.to_string()
        has = 'YES' if needle in s else ''
        if 'Date' in ' '.join(cols) or has:
            print(i, t.shape, cols[:5], needle, has)
            if has:
                print(t.head(3).to_string())
